var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<AppDbContext>();
builder.Services.AddScoped<IOrderService, OrderService>();

var app = builder.Build();

app.MapGet("/api/orders/{id:guid}", async (Guid id, IOrderService service, CancellationToken ct) =>
{
    var order = await service.GetByIdAsync(id, ct);
    return order is null ? Results.NotFound() : Results.Ok(order);
})
.WithName("GetOrder")
.Produces<OrderDto>(StatusCodes.Status200OK)
.Produces(StatusCodes.Status404NotFound);

app.MapPost("/api/orders", async (CreateOrderRequest request, IOrderService service, CancellationToken ct) =>
{
    var result = await service.CreateAsync(request, ct);
    return Results.CreatedAtRoute("GetOrder", new { id = result.Id }, result);
})
.Produces<OrderResult>(StatusCodes.Status201Created);

app.Run();

public class Query
{
    public async Task<Order?> GetOrderAsync(
        Guid id,
        [Service] IOrderService service,
        [Service] ICustomerService customers,
        [Service] IItemService items,
        CancellationToken ct)
    {
        return await service.GetByIdAsync(id, ct);
    }
}

public class OrderType : ObjectType<Order>
{
    protected override void Configure(IObjectTypeDescriptor<Order> d)
    {
        d.Field(o => o.Id);
        d.Field(o => o.Status);
        d.Field(o => o.Total);

        d.Field<CustomerType>(o => o.CustomerId)
            .Resolver(async (ctx, ct) =>
            {
                var order = ctx.Parent<Order>();
                return await ctx.Service<ICustomerService>()
                    .GetByIdAsync(order.CustomerId, ct);
            });

        d.Field<ListType<OrderItemType>>(o => o.Items)
            .Resolver(async (ctx, ct) =>
            {
                var order = ctx.Parent<Order>();
                return await ctx.Service<IItemService>()
                    .GetByOrderIdAsync(order.Id, ct);
            });
    }
}
